result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "raycast.py", "content": """"Ray vs AABB intersection via the slab method.

Returns (hit, tmin):
  hit  -- bool, True if the ray intersects the axis-aligned box
  tmin -- distance along `direction` to the nearest hit point;
          0.0 if the ray origin lies inside the box;
          math.inf on miss.

Zero direction components (including signed zeros like -0.0) are handled
explicitly: instead of dividing by them (which raises ZeroDivisionError in
Python even for floats), rays parallel to a slab are tested against the
slab interval directly.
"""

import math


def ray_aabb(origin, direction, box_min, box_max):
    """Intersect ray (origin, direction) with AABB [box_min, box_max].

    All arguments are 3-tuples of floats. `direction` need not be normalized;
    tmin is in units of |direction|.
    """
    t_lo = -math.inf  # farthest slab-entry
    t_hi = math.inf   # nearest slab-exit

    for o, d, lo, hi in zip(origin, direction, box_min, box_max):
        if d == 0.0:  # True for +0.0 and -0.0
            # Parallel to this slab: must lie within it, contributes no t-interval.
            if o < lo or o > hi:
                return (False, math.inf)
            continue

        inv = 1.0 / d
        t1 = (lo - o) * inv
        t2 = (hi - o) * inv
        if t1 > t2:
            t1, t2 = t2, t1
        t_lo = max(t_lo, t1)
        t_hi = min(t_hi, t2)
        if t_lo > t_hi:
            return (False, math.inf)

    # Box is behind the ray origin iff nearest exit t_hi < 0.
    if t_hi < 0.0:
        return (False, math.inf)

    return (True, max(t_lo, 0.0))
